while (i := input("Anzahl der Personen: ")): print(f"Die Wahrscheinlichkeit, dass von {k} mindestens zwei Personen am selben Tag Geburtstag haben, beträgt: {100 * (1 - eval('*'.join(list(map(str,range(1,365+1))))) / (eval('*'.join(list(map(str,range(1,365+1-k))))) * 365 ** k)):.2f}%\n{'-' * 50}") if i.isnumeric() and 0 < (k := int(i)) < 366 else  print(f"Die Eingabe '{i}' ist keine gültige Zahl im Bereich von 1 bis 365. Bitte versuchen Sie es erneut.\n{'-' * 50}")